# -*- coding: utf-8 -*-
"""Scraper basico de paginas web"""

import requests
from html.parser import HTMLParser


class TitleExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_title = False
        self.title = ""

    def handle_starttag(self, tag, attrs):
        if tag == "title":
            self.in_title = True

    def handle_data(self, data):
        if self.in_title:
            self.title += data

    def handle_endtag(self, tag):
        if tag == "title":
            self.in_title = False


def scrape(url):
    """Scrapear titulo de una pagina"""
    response = requests.get(url, timeout=10)
    parser = TitleExtractor()
    parser.feed(response.text)
    return {"url": url, "title": parser.title, "status": response.status_code}


if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("Uso: python scraper.py <url>")
        sys.exit(1)

    result = scrape(sys.argv[1])
    print(f"URL: {result['url']}")
    print(f"Titulo: {result['title']}")
    print(f"Status: {result['status']}")
